#!/usr/bin/env python3
import json
import sys

def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        sys.stderr.write("Invalid request\n")
        sys.exit(2)

    if not isinstance(data, dict):
        sys.stderr.write("Invalid request\n")
        sys.exit(2)

    if 'subtotal_cents' not in data or 'member' not in data:
        sys.stderr.write("Invalid request\n")
        sys.exit(2)

    subtotal = data['subtotal_cents']
    member = data['member']

    if not isinstance(subtotal, int) or subtotal < 0:
        sys.stderr.write("Invalid request\n")
        sys.exit(2)

    if not isinstance(member, bool):
        sys.stderr.write("Invalid request\n")
        sys.exit(2)

    discount = 0
    if subtotal > 10000:
        discount = subtotal * 10 // 100

    shipping = 750 if not member else 0
    total = subtotal - discount + shipping
    if total < 0:
        total = 0

    output = {
        "subtotal_cents": subtotal,
        "discount_cents": discount,
        "shipping_cents": shipping,
        "total_cents": total,
    }

    json.dump(output, sys.stdout)
    sys.stdout.write("\n")
    sys.exit(0)

if __name__ == "__main__":
    main()
